import{_ as e,a as t,b as a,c as o,d as i,e as s}from"./chunks/m1.CNMM_oxP.js";import{_ as r,c as n,o as l,a6 as d}from"./chunks/framework.Dk6vZ2f8.js";const x=JSON.parse('{"title":"Sun-Panel V2 Development Version Released","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"v2/index.md","filePath":"v2/index.md","lastUpdated":1793535853000}'),c={name:"v2/index.md"},p=d('<h1 id="sun-panel-v2-development-version-released" tabindex="-1">Sun-Panel V2 Development Version Released <a class="header-anchor" href="#sun-panel-v2-development-version-released" aria-label="Permalink to &quot;Sun-Panel V2 Development Version Released&quot;">​</a></h1><h2 id="bug-feedback-feature-suggestions-testing-group" tabindex="-1">BUG Feedback / Feature Suggestions / Testing Group <a class="header-anchor" href="#bug-feedback-feature-suggestions-testing-group" aria-label="Permalink to &quot;BUG Feedback / Feature Suggestions / Testing Group&quot;">​</a></h2><ul><li>V2 QQ Group: 924455282 (or <code>@author</code> in any Sun-Panel group, we listen to all suggestions)</li><li>Feedback address: <a href="https://txc.qq.com/products/798902" target="_blank" rel="noreferrer">https://txc.qq.com/products/798902</a></li><li>GitHub Issues: <a href="https://github.com/hslr-s/sun-panel/issues" target="_blank" rel="noreferrer">https://github.com/hslr-s/sun-panel/issues</a></li><li>Micro app developers, add the author&#39;s WeChat (95302870), note: <code>micro app</code>, the author will add you to the developer group for better communication</li></ul><h2 id="important-notes-for-the-development-version" tabindex="-1">Important Notes for the Development Version <a class="header-anchor" href="#important-notes-for-the-development-version" aria-label="Permalink to &quot;Important Notes for the Development Version&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">❗️❗️❗️❗️❗️ Must Read! Must Read! Must Read! ❗️❗️❗️❗️❗️</p><ul><li>The development version <strong>has a development version note at the bottom</strong>, please do not directly apply it in a public production environment.</li><li>v2 is currently in the development and testing phase, and some uncontrollable BUGs may appear. If you pursue stability, especially <strong>those who are new to AI, Docker, and NAS</strong>, <strong>we do not recommend trying the v2 development version</strong>.</li><li>The V2 development version already supports covering updates from V1 via upgrade, but the feature is still being tested. ❗️⚠️<strong>Please do not follow this operation</strong>⚠️❗️. Please use the v1 export backup package to restore and experience it in a separately deployed v2.</li><li>After the test version (Beta) is released, the development version will only support offline use and cannot log in to the Sun-Panel PRO account, so please do not apply it in a production environment.</li><li>A small number of v1 features have not yet been adapted in the first few versions, and will be gradually adapted later. Please refer to the feature list below.</li></ul></div><h3 id="development-version-benefits" tabindex="-1">Development Version Benefits <a class="header-anchor" href="#development-version-benefits" aria-label="Permalink to &quot;Development Version Benefits&quot;">​</a></h3><p>To release the official v2 version faster, we hope to invite more users to experience the new version&#39;s features. Therefore, for the development version (excluding the v2 test version for now), simply logging into the <a href="https://pro.sun-panel.top" target="_blank" rel="noreferrer">Sun-Panel Service Platform</a> account on the development version allows you to use PRO features for free and access advanced features.</p><p>During the development version (DEV) testing period, users who participate in testing and can propose effective BUGs (first-time proposals) will have their names publicly announced after the official version is released. Depending on the effective count, they can purchase a permanent PRO license at a discount (20% off / 50% off).</p><h3 id="inviting-developers-and-ai-development-experts-to-develop-micro-apps-and-widgets" tabindex="-1">Inviting Developers and AI Development Experts to Develop Micro Apps and Widgets <a class="header-anchor" href="#inviting-developers-and-ai-development-experts-to-develop-micro-apps-and-widgets" aria-label="Permalink to &quot;Inviting Developers and AI Development Experts to Develop Micro Apps and Widgets&quot;">​</a></h3><p>Refer to the documentation <a href="/micro_app_dev/index.html">Micro App Development</a>. The documentation is constantly being improved. Add the author&#39;s WeChat (95302870), note: <code>micro app</code>, the author will add you to the developer group for better communication.</p><h2 id="v2-features" tabindex="-1">V2 Features <a class="header-anchor" href="#v2-features" aria-label="Permalink to &quot;V2 Features&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The following lists the features completed compared to v1. Icon cards retain the v1 style while supporting more sizes for cards in the same group. Of course, there&#39;s much more than this; we&#39;ve just picked a few simple ones. Suggestions are welcome!</p></div><ul class="contains-task-list"><li>✅ Added micro app / widget card framework, enhancing infinite playability in limited screen space, with flexible installation and uninstallation. Developers who love development can freely develop according to the specifications.</li><li>✅ Brand new network environment detection solution, which can match the appropriate LAN address, custom address within the same network segment based on the current page access address.</li><li>✅ Added card custom addresses, which can participate in network environment identification for smart opening or right-click menu opening.</li><li>✅ Refactored the navigation page, <ul><li>Cross-group card dragging</li><li>Support mixing different sizes (currently supports 【ratio (row x column)】<code>1x1</code>,<code>1x2</code>,<code>2x1</code>,<code>2x2</code>,<code>2x4</code>,<code>1xscreen width</code>). Micro app developers can refer to this config to develop widgets of different sizes.</li><li>Perfect mobile adaptation for widgets and other sized cards</li><li>Streamlined card DOM</li></ul></li><li>✅ Docker manager changed from the original list to a card style, with better display effect</li><li>✅ Brand new Docker card, 2x2 card supports displaying container&#39;s real-time network speed and cumulative traffic.</li><li>✅ Icon cards support remark text, visible only when logged in.</li><li>✅ Binary files, added Mac (arm64, amd64) binary file support, removed cgo sqlite library support, adopted full Go sqlite library (binaries for all platforms not fully tested, feedback from testers appreciated, thank you)</li><li>✅ Import v1 icon config data</li><li>✅ Backup feature adaptation</li><li>✅ Gallery batch delete feature</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Integrate third-party self-hosted icon library</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Built-in features (docker, system monitoring, etc.) widgets</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Sidebar directory</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> v1 version system status component adaptation</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> More third-party micro app / widget adaptations</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> More to come...</li></ul><h2 id="installation-method" tabindex="-1">Installation Method <a class="header-anchor" href="#installation-method" aria-label="Permalink to &quot;Installation Method&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Consistent with the <a href="/usage/quick_deploy.html">v1 installation method</a>. <strong>This is a development version, currently incompatible with v1 data, please do not cover update and apply it in a production environment</strong> ::::</p><ul><li>Development version pull command <code>docker pull hslr/sun-panel:2.0.1-dev-latest</code> The document update may not be timely. The docker tag name can be found in the v2 test group announcement. Or refer to the docker official site: <a href="https://hub.docker.com/r/hslr/sun-panel/tags" target="_blank" rel="noreferrer">https://hub.docker.com/r/hslr/sun-panel/tags</a></li><li>Binary file download address: <a href="https://pan.quark.cn/s/74ece0eb087b" target="_blank" rel="noreferrer">Quark Drive</a></li></ul><h2 id="v2-preview-images" tabindex="-1">V2 Preview Images <a class="header-anchor" href="#v2-preview-images" aria-label="Permalink to &quot;V2 Preview Images&quot;">​</a></h2><p><img src="'+e+'" alt=""></p><p><img src="'+t+'" alt=""></p><p><img src="'+a+'" alt=""></p><p><img src="'+o+'" alt=""></p><p><img src="'+i+'" alt="" style="max-width:500px;"></p><p><img src="'+s+'" alt="" style="max-width:500px;"></p></div>',15),u=[p];function h(m,v,f,g,b,k){return l(),n("div",null,u)}const _=r(c,[["render",h]]);export{x as __pageData,_ as default};
